export const PROFILES=Object.freeze({streaming:{targetLufs:-14,maxTruePeak:-1,description:'Indicative playback normalization, not a mandatory delivery target'},broadcast:{targetLufs:-23,maxTruePeak:-1,description:'Generic EBU production profile; confirm broadcaster requirements'},premaster:{targetLufs:null,maxTruePeak:null,description:'Preserve dynamics; agree on peak and delivery specification with mastering engineer'}});export function assessProfile(report,id){if(!Object.hasOwn(PROFILES,id))throw Error('Profil inconnu');const p=PROFILES[id],l=report.integrated,peak=report.truePeakDb;const gainDb=Number.isFinite(l)&&p.targetLufs!==null?p.targetLufs-l:null;return {id,gainDb,estimatedPeakAfterGain:gainDb!==null&&Number.isFinite(peak)?peak+gainDb:null,peakOver: p.maxTruePeak!==null&&Number.isFinite(peak)?peak>p.maxTruePeak:null,certified:false,description:p.description};}export function referenceMatch(a,b){if(!Number.isFinite(a.integrated)||!Number.isFinite(b.integrated))throw Error('LUFS mesurés requis');const target=Math.min(a.integrated,b.integrated);return {targetLufs:target,gainA:target-a.integrated,gainB:target-b.integrated,method:'attenuation only; no PCM modification'};}